package br.com.ajudamutua.service;
import br.com.ajudamutua.model.SignedTransparencyReport; import br.com.ajudamutua.repository.SignedTransparencyReportRepository; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.nio.charset.StandardCharsets; import java.security.*; import java.security.spec.*; import java.time.*; import java.util.*;
@Service public class TransparencyReportService {private final CommunityService community;private final SignedTransparencyReportRepository repo;private final CurrentUserService current;private final AuditService audit;private final ObjectMapper mapper;private final String privateKey;private final String publicKey;private final String keyId;
 public TransparencyReportService(CommunityService c,SignedTransparencyReportRepository r,CurrentUserService u,AuditService a,ObjectMapper m,@Value("${TRANSPARENCY_ED25519_PRIVATE_KEY_BASE64:}") String pk,@Value("${TRANSPARENCY_ED25519_PUBLIC_KEY_BASE64:}") String pub,@Value("${TRANSPARENCY_SIGNING_KEY_ID:transparency-v1}") String kid){community=c;repo=r;current=u;audit=a;mapper=m;privateKey=pk;publicKey=pub;keyId=kid;}
 @Transactional @PreAuthorize("hasAnyRole('ADMIN','AUDITOR')") public SignedTransparencyReport generate(LocalDate start,LocalDate end){if(start==null||end==null||end.isBefore(start))throw new IllegalArgumentException("Período inválido");requireKey();try{Map<String,Object> payload=new TreeMap<>();payload.put("periodStart",start);payload.put("periodEnd",end);payload.put("generatedAt",Instant.now().truncatedTo(java.time.temporal.ChronoUnit.SECONDS));payload.put("summary",community.transparency());payload.put("ledger",community.publicLedger());String json=mapper.writeValueAsString(payload);String hash=sha(json);Signature signature=Signature.getInstance("Ed25519");signature.initSign(KeyFactory.getInstance("Ed25519").generatePrivate(new PKCS8EncodedKeySpec(Base64.getDecoder().decode(privateKey))));signature.update(json.getBytes(StandardCharsets.UTF_8));String sig=Base64.getEncoder().encodeToString(signature.sign());SignedTransparencyReport out=repo.save(new SignedTransparencyReport(UUID.randomUUID(),start,end,json,hash,sig,keyId));audit.append(current.require().getId(),"TRANSPARENCY_REPORT_SIGNED","SignedTransparencyReport",out.getId(),"{\"sha256\":\""+hash+"\"}");return out;}catch(Exception e){throw new IllegalStateException("Falha ao assinar relatório",e);}}
 public Optional<SignedTransparencyReport> latest(){return repo.findTopByOrderByCreatedAtDesc();} public Map<String,String> verificationInfo(){return Map.of("algorithm","Ed25519","keyId",keyId,"publicKeyBase64",publicKey==null?"":publicKey);}
 private void requireKey(){if(privateKey==null||privateKey.isBlank())throw new IllegalStateException("TRANSPARENCY_ED25519_PRIVATE_KEY_BASE64 não configurada");} private String sha(String s)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}}
